{{ config(materialized='table') }}

with
quarantined as (
    select
        cartivo_record_id,
        cartivo_order_id,
        cartivo_customer_id,
        order_date,
        order_status,
        currency,
        order_total,
        channel,
        violation_00,
        violation_01
    from {{ ref("ecommerce__cartivo_order__checked") }}
),
violations as (
    select
        'cartivo_record_id_not_null' as rule_name,
        cartivo_record_id,
        cartivo_order_id,
        cartivo_customer_id,
        order_date,
        order_status,
        currency,
        order_total,
        channel
    from quarantined
    where violation_00

    union all

    select
        'cartivo_order_id_not_null' as rule_name,
        cartivo_record_id,
        cartivo_order_id,
        cartivo_customer_id,
        order_date,
        order_status,
        currency,
        order_total,
        channel
    from quarantined
    where violation_01
)

select
    rule_name,
    cartivo_record_id,
    cartivo_order_id,
    cartivo_customer_id,
    order_date,
    order_status,
    currency,
    order_total,
    channel
from violations
